{
  "items": [
    {
      "name": "Finsupp.support_smul",
      "type": " {α : Type u_1} {M : Type u_2} {R : Type u_4} [Zero M] [SMulZeroClass R M] {b : R} {g : α →₀ M} : (b • g).support ⊆ g.support",
      "module": "Mathlib.Data.Finsupp.SMulWithZero"
    },
    {
      "name": "Finsupp.comapDomain_smul_of_injective",
      "type": " {α : Type u_1} {β : Type u_2} {M : Type u_3} {R : Type u_6} [Zero M] [SMulZeroClass R M] {f : α → β} (hf : Function.Injective f) (r : R) (v : β →₀ M) : Finsupp.comapDomain f (r • v) ⋯ = r • Finsupp.comapDomain f v ⋯",
      "module": "Mathlib.Data.Finsupp.SMul"
    },
    {
      "name": "Finsupp.support_smul_eq",
      "type": " {α : Type u_1} {M : Type u_3} {R : Type u_6} [Semiring R] [IsDomain R] [AddCommMonoid M] [Module R M] [Module.IsTorsionFree R M] {b : R} (hb : b ≠ 0) {g : α →₀ M} : (b • g).support = g.support",
      "module": "Mathlib.Data.Finsupp.SMul"
    },
    {
      "name": "Finsupp.comapDomain_smul",
      "type": " {α : Type u_1} {β : Type u_2} {M : Type u_3} {R : Type u_6} [Zero M] [SMulZeroClass R M] {f : α → β} (r : R) (v : β →₀ M) (hfv : Set.InjOn f (f ⁻¹' ↑v.support)) (hfrv : Set.InjOn f (f ⁻¹' ↑(r • v).support) := ⋯) : Finsupp.comapDomain f (r • v) hfrv = r • Finsupp.comapDomain f v hfv",
      "module": "Mathlib.Data.Finsupp.SMul"
    },
    {
      "name": "Submodule.mem_span_set",
      "type": " {R : Type u_1} {M : Type u_2} [Semiring R] [AddCommMonoid M] [Module R M] {m : M} {s : Set M} : m ∈ Submodule.span R s ↔ ∃ c, ↑c.support ⊆ s ∧ (c.sum fun mi r => r • mi) = m",
      "module": "Mathlib.LinearAlgebra.Finsupp.LinearCombination"
    },
    {
      "name": "Finsupp.linearCombination_comapDomain",
      "type": " {α : Type u_1} {M : Type u_2} (R : Type u_3) [Semiring R] [AddCommMonoid M] [Module R M] {α' : Type u_5} {v : α → M} (f : α → α') (l : α' →₀ R) (hf : Set.InjOn f (f ⁻¹' ↑l.support)) : (Finsupp.linearCombination R v) (Finsupp.comapDomain f l hf) = ∑ i ∈ l.support.preimage f hf, l (f i) • v i",
      "module": "Mathlib.LinearAlgebra.Finsupp.LinearCombination"
    },
    {
      "name": "linearDepOn_iff",
      "type": " {ι : Type u'} {R : Type u_2} {s : Set ι} {M : Type u_4} [Ring R] [AddCommGroup M] [Module R M] {v : ι → M} : ¬LinearIndepOn R v s ↔ ∃ f ∈ Finsupp.supported R R s, ∑ i ∈ f.support, f i • v i = 0 ∧ f ≠ 0",
      "module": "Mathlib.LinearAlgebra.LinearIndependent.Defs"
    },
    {
      "name": "linearDepOn_iffₛ",
      "type": " {ι : Type u'} {R : Type u_2} {s : Set ι} {M : Type u_4} {v : ι → M} [Semiring R] [AddCommMonoid M] [Module R M] : ¬LinearIndepOn R v s ↔ ∃ f g, f ∈ Finsupp.supported R R s ∧ g ∈ Finsupp.supported R R s ∧ ∑ i ∈ f.support, f i • v i = ∑ i ∈ g.support, g i • v i ∧ f ≠ g",
      "module": "Mathlib.LinearAlgebra.LinearIndependent.Defs"
    }
  ]
}
